class Solution {
    public void pattern14(int n) {
        for(int column = 1; column<=n; column++){
            char currentAlphabet = 'A';
            for(int row=0 ; row<column ; row++){
                System.out.print(currentAlphabet);
                currentAlphabet++;
            }
            System.out.println();
        }
    }
}
